/**
 * Applying the committed migrations.
 *
 * The SQL in `drizzle/` is generated by `pnpm db:generate` and committed; nothing generates SQL at
 * run time. `runMigrations` only has to find that folder and hand it to the migrator that matches the
 * driver behind the `AppDb`.
 */
import { existsSync, readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { migrate as migrateNodePg } from 'drizzle-orm/node-postgres/migrator'
import type { NodePgDatabase } from 'drizzle-orm/node-postgres'
import { migrate as migratePglite } from 'drizzle-orm/pglite/migrator'
import type { PgliteDatabase } from 'drizzle-orm/pglite'
import type { AppDb } from './client.js'
import type * as schema from './schema.js'

/**
 * Finds `<package root>/drizzle`, the package root being the first directory at or above this module
 * whose `package.json` is this package's. That holds whether the module runs from `src/db/` under
 * vitest or from `dist/db/` after a build — and the search stops there rather than at the filesystem
 * root, so a stray `drizzle/` further up the tree can never be mistaken for ours.
 *
 * Task 7 ships `drizzle/` (and `data/`) beside `dist/` in the image, keeping that layout intact; the
 * `build` script itself only compiles.
 */
export function migrationsFolder(): string {
  const folder = join(packageRoot(), 'drizzle')
  if (!existsSync(join(folder, 'meta', '_journal.json'))) {
    throw new Error(`no drizzle migrations in ${folder}: the package root was found from ${fileURLToPath(import.meta.url)}, but its migrations were not shipped alongside it`)
  }
  return folder
}

/**
 * The directory holding this package's `package.json` — the anchor for everything shipped beside
 * `dist/` rather than compiled into it: `drizzle/` and `data/` (the item and achievement catalogues).
 * Exported because those loaders need exactly the same search, and two copies of it could disagree.
 */
export function packageRoot(): string {
  const from = fileURLToPath(import.meta.url)
  let dir = dirname(from)
  for (;;) {
    if (isPackageRoot(dir)) return dir
    const parent = dirname(dir)
    if (parent === dir) throw new Error(`no @bp/normal-server package root above ${from}`)
    dir = parent
  }
}

function isPackageRoot(dir: string): boolean {
  const manifest = join(dir, 'package.json')
  if (!existsSync(manifest)) return false
  try {
    return (JSON.parse(readFileSync(manifest, 'utf8')) as { name?: unknown }).name === '@bp/normal-server'
  } catch {
    return false
  }
}

export async function runMigrations(db: AppDb, kind: 'pg' | 'pglite'): Promise<void> {
  const config = { migrationsFolder: migrationsFolder() }
  // `AppDb` is the supertype both driver databases satisfy; `kind` is the caller telling us which
  // one this actually is, which is the one thing the type cannot say.
  if (kind === 'pg') await migrateNodePg(db as NodePgDatabase<typeof schema>, config)
  else await migratePglite(db as PgliteDatabase<typeof schema>, config)
}
